insert into public.hospitals (hospital_id, slug, name, name_spoken_te, name_spoken_hi, name_aliases, area_id, type, address, rating, highlight, specialities, facilities, opd_hours, languages_spoken, faqs, phone, accent_color, is_sample_data) values
  ('h_jh_01', 'hillcrest-multispeciality-hospital-jubilee-hills', 'Hillcrest Multispeciality Hospital', 'హిల్‌క్రెస్ట్ మల్టీస్పెషాలిటీ హాస్పిటల్', 'हिलक्रेस्ट मल्टीस्पेशलिटी हॉस्पिटल', array['hillcrest', 'hill crest', 'hillcrest hospital']::text[], 'jubilee_hills', 'multi-speciality hospital', 'Sunbird Avenue, Jubilee Hills', 4.6, 'Large multi-speciality hospital with a 24x7 emergency wing.', array['General Medicine', 'Gynecology', 'Pediatrics', 'Orthopedics', 'Cardiology']::text[], '{"emergency_24x7": true, "pharmacy": true, "lab": true, "ambulance": true, "cashless_insurance": true, "wheelchair_access": true}'::jsonb, '{"mon": "08:00-21:00", "tue": "08:00-21:00", "wed": "08:00-21:00", "thu": "08:00-21:00", "fri": "08:00-21:00", "sat": "08:00-21:00", "sun": "08:00-21:00"}'::jsonb, array['Telugu', 'Hindi', 'English']::text[], '[{"q": "Is parking available?", "a_en": "Yes, visitor parking is available at the entrance.", "a_te": "Avunu andi, entrance daggara visitors ki parking undi.", "a_hi": "Haan ji, entrance ke paas visitors ki parking hai."}, {"q": "Do you accept cashless insurance?", "a_en": "Yes, we accept cashless insurance from most major insurers; please bring your card.", "a_te": "Avunu andi, chala insurance companies tho cashless undi; card teesukuni randi.", "a_hi": "Haan ji, zyadatar insurance companies ka cashless chalta hai; card le aaiye."}, {"q": "What are the OPD timings?", "a_en": "OPD is open every day, 08:00-21:00.", "a_te": "OPD prathi roju untundi andi, 08:00-21:00.", "a_hi": "OPD roz khula hai ji, 08:00-21:00."}, {"q": "Can I walk in without an appointment?", "a_en": "Walk-ins are welcome, but booked appointments are seen first.", "a_te": "Walk-in ga ravachu andi, kani appointment unna vallani mundu chustaru.", "a_hi": "Walk-in aa sakte hain ji, lekin appointment waalon ko pehle dekha jaata hai."}, {"q": "Do you have a 24x7 emergency?", "a_en": "Yes, our emergency is open 24x7. In an emergency, please call 108 or 112 first.", "a_te": "Avunu andi, emergency 24x7 open. Emergency aithe mundu 108 leda 112 ki call cheyyandi.", "a_hi": "Haan ji, emergency 24x7 khula hai. Emergency mein pehle 108 ya 112 pe call kijiye."}]'::jsonb, 'DEMO-H-001', '#0F766E', true),
  ('h_jh_02', 'lotus-skin-child-clinic-jubilee-hills', 'Lotus Skin & Child Clinic', 'లోటస్ స్కిన్ అండ్ చైల్డ్ క్లినిక్', 'लोटस स्किन एंड चाइल्ड क्लिनिक', array['lotus clinic', 'lotus', 'lotus skin clinic']::text[], 'jubilee_hills', 'clinic', 'Lily Pond Lane, Jubilee Hills', 4.3, 'Neighbourhood clinic for skin care and children''s health.', array['Dermatology', 'Pediatrics']::text[], '{"emergency_24x7": false, "pharmacy": true, "lab": false, "ambulance": false, "cashless_insurance": true, "wheelchair_access": true}'::jsonb, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-20:00"}'::jsonb, array['Telugu', 'Hindi', 'English']::text[], '[{"q": "Is parking available?", "a_en": "Yes, visitor parking is available at the entrance.", "a_te": "Avunu andi, entrance daggara visitors ki parking undi.", "a_hi": "Haan ji, entrance ke paas visitors ki parking hai."}, {"q": "Do you accept cashless insurance?", "a_en": "Yes, we accept cashless insurance from most major insurers; please bring your card.", "a_te": "Avunu andi, chala insurance companies tho cashless undi; card teesukuni randi.", "a_hi": "Haan ji, zyadatar insurance companies ka cashless chalta hai; card le aaiye."}, {"q": "What are the OPD timings?", "a_en": "OPD is open every day, 09:00-21:00, and 09:00-20:00 on Sundays.", "a_te": "OPD prathi roju untundi andi, 09:00-21:00, Sunday 09:00-20:00.", "a_hi": "OPD roz khula hai ji, 09:00-21:00, Sunday ko 09:00-20:00."}, {"q": "Can I walk in without an appointment?", "a_en": "Walk-ins are welcome, but booked appointments are seen first.", "a_te": "Walk-in ga ravachu andi, kani appointment unna vallani mundu chustaru.", "a_hi": "Walk-in aa sakte hain ji, lekin appointment waalon ko pehle dekha jaata hai."}, {"q": "Do you have a 24x7 emergency?", "a_en": "We don''t have a 24x7 emergency. In an emergency, please call 108 or 112 right away.", "a_te": "Maa daggara 24x7 emergency ledu